```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly pending: Array<() => Promise<void>> = [];
  private running = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Queues a job. Resolves with its result, or rejects with its last error once retries run out. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.attempt(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves once no jobs are running or waiting. Never rejects. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let failures = 0; ; failures++) {
      try {
        return await job();
      } catch (err) {
        if (failures >= this.maxRetries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.running++;
      void run().finally(() => {
        this.running--;
        this.next();
      });
    }

    if (this.running === 0 && this.pending.length === 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }
}
