```go
// Package argparse is a small command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type option struct {
	long  string
	short byte // 0 if the option has no short form
	help  string
	def   string

	// Exactly one of these is set.
	boolValue *bool
	strValue  *string
}

type positional struct {
	name  string
	help  string
	value *string
}

// Parser holds the flag and argument definitions for one command.
type Parser struct {
	name        string
	summary     string
	options     []*option
	positionals []*positional
}

// New returns a parser for the named command. The summary appears in the help message.
func New(name, summary string) *Parser {
	return &Parser{name: name, summary: summary}
}

// Bool defines a boolean flag that is false unless present. Pass 0 for no short form.
func (p *Parser) Bool(long string, short byte, help string) *bool {
	v := new(bool)
	p.options = append(p.options, &option{long: long, short: short, help: help, boolValue: v})
	return v
}

// String defines a flag that takes a value. Pass 0 for no short form.
func (p *Parser) String(long string, short byte, def, help string) *string {
	v := new(string)
	*v = def
	p.options = append(p.options, &option{long: long, short: short, help: help, def: def, strValue: v})
	return v
}

// Arg defines a required positional argument. Arguments are filled in definition order.
func (p *Parser) Arg(name, help string) *string {
	v := new(string)
	p.positionals = append(p.positionals, &positional{name: name, help: help, value: v})
	return v
}

// Parse reads args (usually os.Args[1:]) into the defined flags and arguments.
// It returns any positional arguments beyond the defined ones.
func (p *Parser) Parse(args []string) ([]string, error) {
	var operands []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			operands = append(operands, args[i+1:]...)
			break
		}
		// A lone "-" conventionally means stdin, so it counts as positional.
		if len(arg) < 2 || arg[0] != '-' {
			operands = append(operands, arg)
			continue
		}
		if arg == "-h" || arg == "--help" {
			return nil, ErrHelp
		}

		name, value, hasValue := strings.Cut(arg, "=")
		opt := p.lookup(name)
		if opt == nil {
			return nil, fmt.Errorf("unknown flag %s", name)
		}
		if opt.boolValue != nil {
			if hasValue {
				return nil, fmt.Errorf("flag %s does not take a value", name)
			}
			*opt.boolValue = true
			continue
		}
		if !hasValue {
			if i+1 >= len(args) {
				return nil, fmt.Errorf("flag %s needs a value", name)
			}
			i++
			value = args[i]
		}
		*opt.strValue = value
	}

	if len(operands) < len(p.positionals) {
		return nil, fmt.Errorf("missing argument <%s>", p.positionals[len(operands)].name)
	}
	for i, pos := range p.positionals {
		*pos.value = operands[i]
	}
	return operands[len(p.positionals):], nil
}

func (p *Parser) lookup(name string) *option {
	for _, opt := range p.options {
		if strings.HasPrefix(name, "--") {
			if opt.long == name[2:] {
				return opt
			}
		} else if len(name) == 2 && opt.short != 0 && opt.short == name[1] {
			return opt
		}
	}
	return nil
}

// Usage returns the help message generated from the definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [flags]", p.name)
	for _, pos := range p.positionals {
		fmt.Fprintf(&b, " <%s>", pos.name)
	}
	b.WriteString("\n")
	if p.summary != "" {
		fmt.Fprintf(&b, "\n%s\n", p.summary)
	}

	if len(p.positionals) > 0 {
		b.WriteString("\nArguments:\n")
		w := tabwriter.NewWriter(&b, 0, 0, 2, ' ', 0)
		for _, pos := range p.positionals {
			fmt.Fprintf(w, "  <%s>\t%s\n", pos.name, pos.help)
		}
		w.Flush()
	}

	b.WriteString("\nFlags:\n")
	w := tabwriter.NewWriter(&b, 0, 0, 2, ' ', 0)
	for _, opt := range p.options {
		names := "    --" + opt.long
		if opt.short != 0 {
			names = fmt.Sprintf("-%c, --%s", opt.short, opt.long)
		}
		help := opt.help
		if opt.strValue != nil {
			names += " <value>"
			if opt.def != "" {
				help += fmt.Sprintf(" (default %q)", opt.def)
			}
		}
		fmt.Fprintf(w, "  %s\t%s\n", names, help)
	}
	fmt.Fprintf(w, "  -h, --help\tshow this help\n")
	w.Flush()

	return b.String()
}
