const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
```

If the 5 seconds elapse, the request is aborted and `fetch` rejects with a `TimeoutError`:

```js
try {
  const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
  const data = await response.json();
} catch (err) {
  if (err.name === "TimeoutError") {
    // timed out
  } else {
    throw err;
  }
}
```

The timeout covers the whole request, including reading the body, so a slow download can also trigger it during `response.json()`.

`AbortSignal.timeout` is available in Node.js 17.3+ and all current browsers. For older environments, use an `AbortController`, which rejects with an `AbortError` instead:

```js
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), 5000);
try {
  const response = await fetch(url, { signal: controller.signal });
} finally {
  clearTimeout(timer);
}
```

```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;

  return function (...args) {
    const remaining = wait - (Date.now() - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(this, args);
    } else if (!timer) {
      // Schedule one trailing call so the final scroll position is handled.
      timer = setTimeout(() => {
        timer = null;
        last = Date.now();
        fn.apply(this, args);
      }, remaining);
    }
  };
}

window.addEventListener("scroll", throttle(() => {
  console.log(window.scrollY);
}, 200), { passive: true });
```

The handler runs immediately on the first scroll event, then at most once per 200 ms, with one final call after scrolling stops. The trailing call receives the arguments from the event that scheduled it, so read live values such as `window.scrollY` inside the handler instead of relying on the event object.
